---
import Text from "@/components/fundations/typography/Text.astro";
import { Image } from "astro:assets";
import g1 from "@/images/gallery/1.png";
import g2 from "@/images/gallery/2.png";
import g3 from "@/images/gallery/3.png";
import g4 from "@/images/gallery/4.png";
import g5 from "@/images/gallery/5.png";
import g6 from "@/images/gallery/6.png";
---

<section class="bg-white ">
  <div class="px-8 py-24 mx-auto max-w-7xl md:px-12 lg:px-20">
    <div
      class="grid grid-cols-1 sm:grid-cols-2 gap-4 lg:grid-cols-3 lg:col-span-4"
    >
      <div class="flex flex-col gap-4 sm:col-span-2 lg:col-span-1">
        <div class="py-12">
          <Text
            variant="displayMD"
            tag="h2"
            class="font-semibold tracking-tight text-base-900 sm:text-balance"
          >
            Explore our visual showcase
          </Text>
          <Text
            variant="textSM"
            tag="p"
            class="mt-2 font-medium text-base-500 sm:text-balance"
          >
            A curated collection of images capturing the essence of our brand
            and the stories we tell.
          </Text>
        </div>
        <Image
          height={500}
          width={500}
          src={g1}
          alt="#_"
          class="object-cover size-full"
        />
      </div>
      <div class="flex flex-col gap-4 sm:col-span-2 lg:col-span-1">
        <Image
          height={500}
          width={500}
          src={g2}
          alt="#_"
          class="object-cover size-full"
        />
        <Image
          height={500}
          width={500}
          src={g3}
          alt="#_"
          class="object-cover size-full"
        />
      </div>
      <div class="flex flex-col gap-4 sm:col-span-2 lg:col-span-1">
        <Image
          height={500}
          width={500}
          src={g4}
          alt="#_"
          class="object-cover object-top size-full aspect-square"
        />
        <Image
          height={500}
          width={500}
          src={g5}
          alt="#_"
          class="object-cover object-top size-full aspect-square"
        />
        <Image
          height={500}
          width={500}
          src={g6}
          alt="#_"
          class="object-cover object-top size-full aspect-square"
        />
      </div>
    </div>
  </div>
</section>
